        failed = failed + 1
    }

    // T3
    print("T3: det(I) = 1.................. ")
    if test_det_identity() == 1 {
        println("PASS")
        passed = passed + 1
    } else {
        println("FAIL")
        failed = failed + 1
    }

    // T4
    print("T4: QR: Q*R = A, Q^T*Q = I...... ")
